ee:variables.ee:set-variable:
%dw 2.0
output application/json
var response = {
	"API-SpringCM-Forms": vars.springCMResponse.status,
	"DB-Azure-InformaticaGlobalDB": vars.informaticaGlobalDBStatus
}
var failedCount= sizeOf(response filterObject ($ == "Failure") mapObject {($$):$})
var failedComponent= response filterObject ($ == "Failure") mapObject (($$):$)
---
if(failedCount>1) "503" 
else (
   if(failedComponent."API-SpringCM-Forms" != null) "518" 
   else if(failedComponent."DB-Azure-InformaticaGlobalDB" != null) "519"
   else "200")

%dw 2.0
output application/json
var response = {
	"API-SpringCM-Forms": vars.springCMResponse.status,
	"DB-Azure-InformaticaGlobalDB": vars.informaticaGlobalDBStatus
}
var failedCount= sizeOf(response filterObject ($ == "Failure") mapObject {($$):$})
var failedComponent= response filterObject ($ == "Failure") mapObject (($$):$)
---
if(failedCount>1) ""
else (
   if(failedComponent."API-SpringCM-Forms" != null) "SpringCM Error" 
   else if(failedComponent."DB-Azure-InformaticaGlobalDB" != null) "Informatica Global DB Error"
   else "")
